import { GetItemCommand } from 'dynamodb-toolbox/entity/actions/get';
import { QueryCommand } from 'dynamodb-toolbox/table/actions/query';
import { MODELO_PISTA, MODELO_COMPLEJO, TABLA_PISTAS } from '../../models/complejo-pista.model.mjs';

export async function buscarComplejoRepository(complejoId) {
  const { Item } = await MODELO_COMPLEJO.build(GetItemCommand)
    .key({ complejoId }).options({ consistent: true }).send();
  return Item ?? null;
}

export async function consultarComplejoRepository(complejoId, minimo) {
  const { Items = [] } = await TABLA_PISTAS.build(QueryCommand)
    .entities(MODELO_PISTA)
    .query({ index: 'PorComplejo', partition: complejoId })
    .options({ filters: { Pista: { attr: 'superficieM2', gte: minimo } } })
    .send();
  return Items;
}
